// 初始化抓取页面的流程
import { lang } from './Lang'
import { Tools } from './Tools'
import { filter } from './Filter'
import { store } from './Store'
import { log } from './Log'
import { EVT } from './EVT'
import { saveData } from './SaveData'
import {
  PostList,
  Post,
  SupportPostList,
  TagPostList,
  PostBody,
} from './CrawlResult.d'
import { API } from './API'
import { states } from './States'
import { msgBox } from './MsgBox'
import { toast } from './Toast'
import { Utils } from './utils/Utils'
import { crawlInterval } from './CrawlInterval'
import { settings } from './setting/Settings'

abstract class InitPageBase {
  protected init() {
    this.addCrawlBtns()
    this.addAnyElement()
    this.initAny()

    window.addEventListener(EVT.list.pageSwitchedTypeChange, () => {
      this.destroy()
    })

    EVT.bindOnce('crawlCompleteTime', EVT.list.crawlFinish, () => {
      states.crawlCompleteTime = new Date().getTime()
    })

    EVT.bindOnce('downloadCompleteTime', EVT.list.downloadComplete, () => {
      states.downloadCompleteTime = new Date().getTime()
    })
  }

  // 各个子类私有的初始化内容
  protected initAny() {}

  // 销毁初始化页面时添加的元素和事件，恢复设置项等
  protected destroy(): void {
    Tools.clearSlot('crawlBtns')
  }

  // 添加中间按钮
  protected addCrawlBtns() {}

  // 添加其他元素（如果有）
  protected addAnyElement(): void {}

  protected crawlNumber: number = 0 // 要抓取的个数/页数
  protected nextUrl: null | string = null

  /**并发请求数量 */
  private readonly getPostDataThreadMax = 1
  protected getPostDataThreadNum = 0
  protected getPostDatafinished = 0

  protected postListURLs: string[] = []

  protected confirmRecrawl() {
    if (store.result.length > 0) {
      // 如果已经有抓取结果，则检查这些抓取结果是否已被下载过
      // 如果没有被下载过，则显示提醒
      if (states.crawlCompleteTime > states.downloadCompleteTime) {
        const _confirm = window.confirm(lang.transl('_已有抓取结果时进行提醒'))
        return _confirm
      }
    }

    return true
  }

  // 准备抓取，进行抓取之前的一些检查工作。必要时可以在子类中改写
  protected async readyCrawl() {
    if (states.busy) {
      window.alert(lang.transl('_当前任务尚未完成2'))
      return
    }

    if (!this.confirmRecrawl()) {
      return
    }

    EVT.fire('clearLog')

    log.success(lang.transl('_开始抓取'))
    toast.show(lang.transl('_开始抓取'))
    msgBox.resetOnce('tipLinktext')

    EVT.fire('crawlStart')

    this.getPostDataThreadNum = 0
    this.getPostDatafinished = 0
    this.nextUrl = null
    this.postListURLs = []

    // 进入第一个抓取方法
    this.nextStep()
  }

  // 当可以开始抓取时，进入下一个流程。默认情况下，开始获取文章列表。如有不同，由子类自行修改
  protected nextStep() {
    this.FetchPostList()
  }

  /**获取一个作者的文章列表分页网址 */
  // 获取分页数据，然后构造出每次请求该作者 300 篇文章的 URL
  protected async getPostListURLs(creatorId: string) {
    const paginateData: {
      body: {
        pageUrls: string[]
      }
    } = await API.request(
      `https://api.fanbox.cc/post.paginateCreator?creatorId=${creatorId}`,
    )
    // console.log(paginateData.body)

    if (paginateData?.body?.pageUrls?.length > 0) {
      // 分页数据里的 URL 格式如下：
      // https://api.fanbox.cc/post.listCreator?creatorId=usotukiya&maxPublishedDatetime=2024-08-04%2020%3A41%3A47&maxId=8345112&limit=10
      // 每次可以获取 10 个文章的数据，但是 limit 的最大值是 300，可以一次获取 300 篇文章的数据
      // 所以下面每隔 30 个网址保存一次，并把 limit 改成 300

      let index = 0
      const total = paginateData.body.pageUrls.length
      while (index < total) {
        const url = paginateData.body.pageUrls[index]
        this.postListURLs.push(url.replace('limit=10', 'limit=300'))
        index = index + 30
      }
      // this.postListURLs.forEach(url => console.log(url))
    }
  }

  /**获取文章列表数据。如果传入了 URL，则是为了重试抓取该 URL */
  protected async FetchPostList(url?: string) {
    await crawlInterval.wait()

    if (url === undefined) {
      url = this.postListURLs.shift()
      if (url === undefined) {
        log.error(
          `Error in crawling: internal error \n FetchPostList url is undefined\n End Crawling`,
        )
        return this.FetchPostListFinished()
      }
    }

    try {
      const data: PostList = (await API.request(url)) as PostList
      crawlInterval.addTime()
      this.afterFetchPostList(data)
    } catch (error) {
      console.log(error)
      if ((error as Error).message) {
        log.error((error as Error).message)
      }
      log.error(lang.transl('_请求失败下载器会重试这个请求'))
      crawlInterval.addTime('long')
      this.FetchPostList(url)
    }
  }

  protected async FetchPostListOld(url?: string) {
    await crawlInterval.wait()

    if (url === undefined) {
      url = this.postListURLs.shift()
      if (url === undefined) {
        log.error(
          `Error in crawling: internal error \n FetchPostList url is undefined\n End Crawling`,
        )
        return this.FetchPostListFinished()
      }
    }

    try {
      const data: SupportPostList | TagPostList = (await API.request(url)) as
        | SupportPostList
        | TagPostList
      crawlInterval.addTime()
      this.afterFetchPostListOld(data)
    } catch (error) {
      console.log(error)
      if ((error as Error).message) {
        log.error((error as Error).message)
      }
      log.error(lang.transl('_请求失败下载器会重试这个请求'))
      crawlInterval.addTime('long')
      this.FetchPostListOld(url)
    }
  }

  /**保存符合过滤条件的文章的 ID，之后会抓取这些文章的详细数据 */
  protected afterFetchPostList(data: PostList) {
    const useData = data.body.posts || data.body || []
    if (useData.length === 0) {
      return this.noResult()
    }

    for (const item of useData) {
      if (item.body === null) {
        continue
      }
      // 对投稿进行检查，决定是否保留它
      const id = item.id
      const creatorId = item.creatorId
      const fee = item.feeRequired
      const date = item.publishedDatetime
      const title = item.title
      const check = filter.check({ id, creatorId, fee, date, title })
      if (check) {
        store.postIdList.push(id)
      }
    }

    if (this.postListURLs.length > 0) {
      this.FetchPostList()
    } else {
      this.FetchPostListFinished()
    }
  }

  protected afterFetchPostListOld(data: SupportPostList | TagPostList) {
    if (data.body.items.length === 0) {
      return this.noResult()
    }

    const items = data.body.items
    this.nextUrl = data.body.nextUrl

    for (const item of items) {
      if (item.body === null) {
        continue
      }
      // 针对投稿进行检查，决定是否保留它
      const id = item.id
      const creatorId = item.creatorId
      const fee = item.feeRequired
      const date = item.publishedDatetime
      const title = item.title
      const check = filter.check({ id, creatorId, fee, date, title })
      if (check) {
        store.postIdList.push(id)
      }
    }

    if (this.nextUrl) {
      this.FetchPostListOld(this.nextUrl)
    } else {
      this.FetchPostListFinished()
    }
  }

  /**获取了要抓取的文章的 ID 列表之后，开始抓取每个文章的详细数据 */
  protected FetchPostListFinished() {
    log.log(lang.transl('_列表页抓取完成'))

    if (store.postIdList.length === 0) {
      return this.noResult()
    }

    log.log(lang.transl('_当前有x个投稿', store.postIdList.length.toString()))
    log.log(lang.transl('_开始获取投稿信息'))

    for (let i = 0; i < this.getPostDataThreadMax; i++) {
      const postId = store.postIdList.shift()
      if (postId) {
        this.getPostDataThreadNum++
        this.fetchPost(postId)
      } else {
        break
      }
    }
  }

  protected async fetchPost(postId: string) {
    await crawlInterval.wait()

    try {
      const data = await API.getPost(postId)
      crawlInterval.addTime()
      // 把评论合并进投稿数据里，从 afterFetchPost 的角度看，相当于 post.info 自带评论
      await this.fetchAllComments(data.body.post || data.body)
      this.afterFetchPost(data)
    } catch (error) {
      console.log(error)
      if ((error as Error).message) {
        log.error((error as Error).message)
      }
      log.error(lang.transl('_请求失败下载器会重试这个请求'))
      crawlInterval.addTime('long')
      this.fetchPost(postId)
    }
  }

  protected afterFetchPost(data: Post) {
    saveData.receive(data.body.post || data.body)
    log.log(`${lang.transl('_待处理')} ${store.postIdList.length}`, 1, false)
    // 当抓取完一个文章之后，如果还有等待抓取的文章就继续抓取
    // 否则当前抓取线程结束。等待所有抓取线程完成之后，文章数据就全部获取了
    const postId = store.postIdList.shift()
    if (postId) {
      this.fetchPost(postId)
    } else {
      this.getPostDatafinished++
      if (this.getPostDatafinished == this.getPostDataThreadNum) {
        this.crawlFinished()
      }
    }
  }

  // 抓取完毕
  protected crawlFinished() {
    if (store.skipDueToFee > 0) {
      log.warning(
        lang.transl('_因为价格限制而跳过的投稿数量') + store.skipDueToFee,
      )
    }
    if (store.result.length === 0) {
      return this.noResult()
    }

    // 把抓取结果按照 postid 升序排列
    store.result.sort(Utils.sortByProperty('postId', 'asc'))

    store.date = new Date()

    log.log(lang.transl('_抓取文件数量', store.result.length.toString()))

    log.success(lang.transl('_抓取完毕'), 2)

    EVT.fire('crawlFinish')
    // console.log(store.result)
  }

  // 获取投稿的全部评论，把结果合并到 post 的 commentList 里
  // FANBOX 的 post.info 不再返回评论，需要调用评论接口 post.getComments，使用 offset 分页
  protected async fetchAllComments(post: PostBody) {
    // 未开启保存评论时不做任何事
    if (!settings.saveComment) {
      return
    }
    // commentCount 为 0 的投稿没有评论，不需要请求
    if (post.commentCount === 0) {
      return
    }

    const limit = 50
    let items: any[] = []
    let nextUrl: string | null = null

    try {
      await crawlInterval.wait()
      const data = await API.getPostComments(post.id, 0, limit)
      crawlInterval.addTime()
      items = data.body.commentList.items
      nextUrl = data.body.commentList.nextUrl
    } catch (error) {
      console.log(error)
      return
    }

    // 翻页获取剩余评论：优先跟随 nextUrl，否则按 offset 递增
    // 当一页返回不足 limit 条时，说明没有更多评论了
    // 最多获取 20 页（1000 条评论），防止异常情况导致无限请求
    let page = 1
    let hasMore = items.length >= limit
    while (page < 20 && (nextUrl || hasMore)) {
      try {
        page++
        await crawlInterval.wait()
        let list: { items: any[]; nextUrl: string | null }
        if (nextUrl) {
          const data: any = await API.request(nextUrl)
          list = data.body.commentList
        } else {
          const data = await API.getPostComments(post.id, items.length, limit)
          list = data.body.commentList
        }
        crawlInterval.addTime()
        items = items.concat(list.items)
        nextUrl = list.nextUrl
        hasMore = list.items.length >= limit
      } catch (error) {
        // 评论分页请求失败时停止获取更多评论，避免无限重试
        console.log(error)
        break
      }
    }

    // 去重，防止分页返回重复数据
    const seen = new Set<string>()
    items = items.filter((comment: any) => {
      if (!comment || !comment.id || seen.has(comment.id)) {
        return false
      }
      seen.add(comment.id)
      return true
    })

    // 把结果写入 post.commentList，供保存流程使用
    post.commentList = { items, nextUrl: null }
  }

  // 抓取结果为 0 时输出提示
  protected noResult() {
    EVT.fire('crawlFinish')
    EVT.fire('crawlEmpty')
    log.error(lang.transl('_抓取结果为零'), 2)
    msgBox.error(lang.transl('_抓取结果为零'))
  }
}

export { InitPageBase }
